    var s = r.pick(sets);
    var lcm = s.reduce(function (a, b) { return a * b / gcd(a, b); }), parts = s.map(function (x) { return lcm / x; }), tot = parts[0] + parts[1] + parts[2];
    var k = r.int(1, 4), herd = tot * k, i = r.int(0, 2), ans = parts[i] * k;
    var who = ['үлкен ұлына', 'ортаншы ұлына', 'кенже ұлына'], whoR = ['старшему', 'среднему', 'младшему'];
